// Generated by OpenCode AI - Auth Flow Setup - 2026-02-12
import '../global.css';
import { ThemeProvider } from '@react-navigation/native';
import { KeyboardProvider } from 'react-native-keyboard-controller';
import { PortalHost } from '@rn-primitives/portal';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { StatusBar } from 'expo-status-bar';
import { Stack } from 'expo-router';
import { NAV_THEME } from '@/lib/theme';
import { useColorScheme } from 'nativewind';
import { useAuth } from '@/lib/useAuth';
import { SplashScreen } from '@/components/SplashScreen';
import React from 'react';

/**
 * Root Layout with authentication-based routing
 *
 * Flow:
 * 1. Show SplashScreen while checking auth state
 * 2. If authenticated → show (main) group (tabs navigation)
 * 3. If not authenticated → show (auth) group (login/register)
 *
 * TODO: When integrating Better Auth + Convex:
 * - Update useAuth hook to use real auth state
 * - Add session persistence
 * - Handle token refresh
 */
export default function RootLayout() {
  const { colorScheme } = useColorScheme();
  const { isAuthenticated, isLoading } = useAuth();

  // Show splash screen while determining auth state
  if (isLoading) {
    return <SplashScreen />;
  }

  return (
    <SafeAreaProvider>
      <KeyboardProvider>
        <ThemeProvider value={NAV_THEME[colorScheme ?? 'light']}>
          <StatusBar style={colorScheme === 'dark' ? 'light' : 'dark'} />
          <Stack screenOptions={{ headerShown: false }}>
            {/* Protected routes - only accessible when authenticated */}
            <Stack.Protected guard={isAuthenticated}>
              <Stack.Screen name="(main)" />
            </Stack.Protected>

            {/* Public routes - only accessible when NOT authenticated */}
            <Stack.Protected guard={!isAuthenticated}>
              <Stack.Screen name="(auth)" />
            </Stack.Protected>
          </Stack>
          <PortalHost />
        </ThemeProvider>
      </KeyboardProvider>
    </SafeAreaProvider>
  );
}
